<div class="d-flex flex-wrap justify-content-between mb-3 gap-2"><div><h4 class="mb-0"><?= e($po['po_no']) ?> <?= badge($po['status']) ?></h4><div class="text-muted"><?= link_supplier($po['supplier_id'], $po['supplier']) ?> &rarr; <?= link_wh($po['warehouse_id'], $po['warehouse']) ?> &middot; <?= e($po['order_date']) ?></div></div>
<div class="d-flex gap-1 flex-wrap align-self-start">
<?php $btn = function ($to, $label, $cls, $perm, $ok) use ($po) { if (!Auth::can($perm) || !in_array($po['status'], $ok, true)) return; ?><form method="post" action="<?= url('purchasing/status') ?>" data-confirm="<?= e($label) ?>?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$po['id'] ?>"><input type="hidden" name="to" value="<?= $to ?>"><button class="btn btn-<?= $cls ?>"><?= e($label) ?></button></form><?php };
if ($po['status'] === 'draft' && Auth::can('inventory.purchasing.create')): ?><a class="btn btn-outline-primary" href="<?= url('purchasing/form', ['id' => $po['id']]) ?>"><i class="bi bi-pencil"></i> Edit</a><?php endif;
$btn('submitted', 'Submit', 'primary', 'inventory.purchasing.create', ['draft']); $btn('approved', 'Approve', 'success', 'inventory.purchasing.approve', ['submitted']); $btn('cancelled', 'Cancel PO', 'outline-danger', 'inventory.purchasing.approve', ['draft', 'submitted', 'approved']);
if (in_array($po['status'], ['approved', 'partial'], true) && Auth::can('inventory.purchasing.receive')): ?><a class="btn btn-success" href="<?= url('purchasing/receive', ['id' => $po['id']]) ?>"><i class="bi bi-box-arrow-in-down"></i> Receive goods</a><?php endif; ?>
<a class="btn btn-outline-secondary" href="javascript:window.print()"><i class="bi bi-printer"></i></a></div></div>
