<?php foreach ($items as $i): ?><tr><td><?= e($i['sku']) ?></td><td><?= link_product($i['product_id'], $i['name']) ?></td><td class="text-end"><?= fq($i['qty']) ?></td><td class="text-end"><?= fq($i['received_qty']) ?></td><td class="text-end"><?= number_format($i['price'], 2) ?></td><td class="text-end"><?= number_format($i['qty'] * $i['price'], 2) ?></td></tr><?php endforeach; ?>
<tr class="fw-bold"><td colspan="5" class="text-end">Total</td><td class="text-end"><?= e(money($po['total'])) ?></td></tr></tbody></table></div>
